// Controller layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Connects the workflow and domain to the page. No business logic here.
import { useMachine } from "@xstate/react";
import { productsHistoryWorkflow } from "../workflow/products-history.workflow.js";
import * as domain from "../domain/products-history.domain.js";
import ProductsHistoryPage from "../page/ProductsHistoryPage.jsx";

export default function ProductsHistoryController() {
  const [state, send] = useMachine(productsHistoryWorkflow);
  const { items, selectedId, error } = state.context;

  return (
    <ProductsHistoryPage
      status={String(state.value)}
      error={error}
      productCount={domain.productCount(items)}
      stockTotal={domain.stockTotal(items)}
      avgPrice={domain.avgPrice(items)}
      rows={domain.toProductsHistoryRows(items)}
      selectedId={selectedId}
      formValues={domain.toFormValues(domain.findProductsHistory(items, selectedId))}
      onEdit={(id) => send({ type: "EDIT", id })}
      onDelete={(id) => send({ type: "DELETE", id })}
      onSave={(values) => send({ type: "SAVE", data: domain.toProductsHistoryInput(values) })}
      onCancel={() => send({ type: "CANCEL" })}
    />
  );
}
